const latest={};
sl.filter(r=>r&&r.ID&&(r.No_Item!==''&&r.No_Item!==undefined&&r.No_Item!==null)&&r.Status)
  .forEach(r=>{const raw={Open:'pending',Proses:'inprogress',Selesai:'done',Reject:'done'};const v=String(r.Status).trim();latest[String(r.ID).trim()+'|'+String(r.No_Item).trim()]=raw[v]||v.toLowerCase();});
const filt=ri.filter(r=>{const rp=(r.Pekerja||'').toString().trim(),rpr=(r.Proyek||'').toString().trim();
  if(fP&&rp!==fP)return false;if(fPr&&rpr!==fPr)return false;return true;});
const g={};
filt.forEach(r=>{const bid=String(r.Batch_ID||'').trim();if(!bid)return;
  if(!g[bid])g[bid]={id:bid,project:String(r.Proyek||'').trim(),pekerja:String(r.Pekerja||'').trim(),tanggal:String(r.Tanggal||'').trim(),catatan:String(r.Catatan||'').trim(),items:[],total:0};
  const no=parseInt(r.No_Item)||g[bid].items.length+1;
  g[bid].items.push({no,pekerjaan:String(r.Pekerjaan||'').trim(),vol:parseFloat(r.Vol)||0,sat:String(r.Sat||'').trim(),
    harga_satuan:parseFloat(r.Harga_Satuan)||0,total:parseFloat(r.Total_Item)||0,status:latest[bid+'|'+no]||'pending'});
  if(r.Total_Keseluruhan&&!g[bid].total)g[bid].total=parseFloat(r.Total_Keseluruhan)||0;});
Object.values(g).forEach(x=>{if(!x.total)x.total=x.items.reduce((s,it)=>s+(it.total||0),0);});
const data=Object.values(g).sort((a,b)=>new Date(b.tanggal)-new Date(a.tanggal));
return [{json:{success:true,count:data.length,data}}];

