function R(vr){if(!vr||!vr.values||vr.values.length<2)return [];const h=vr.values[0];return vr.values.slice(1).map(row=>{const o={};h.forEach((k,i)=>o[k]=(row[i]!==undefined?row[i]:''));return o;});}
const vr=($input.first().json.valueRanges)||[];
const tiket=R(vr[0]).filter(r=>r.ID&&r.Proyek);
const items=R(vr[1]).filter(r=>r.Proyek);
const budg=R(vr[2]).filter(r=>r.Proyek&&r.Kategori);
const num=v=>{const n=parseFloat(String(v).replace(/[^0-9.-]/g,''));return isNaN(n)?0:n;};
const projNames=[...new Set([...tiket.map(r=>String(r.Proyek).trim()),...budg.map(r=>String(r.Proyek).trim())])].filter(Boolean);
const today=new Date().toISOString().slice(0,10);
const statusBucket=s=>{s=String(s||'').toLowerCase();
  if(s==='selesai'||s==='closed'||s==='done')return 'Selesai';
  if(s==='proses'||s==='inprogress'||s==='in progress')return 'Proses';
  return 'Pending';};
const projects=projNames.map(name=>{
  const tk=tiket.filter(r=>String(r.Proyek).trim()===name);
  const it=items.filter(r=>String(r.Proyek).trim()===name);
  const bd=budg.filter(r=>String(r.Proyek).trim()===name);
  const sc={Pending:0,Proses:0,Selesai:0};
  tk.forEach(r=>{sc[statusBucket(r.Status)]++;});
  const kritisAktif=tk.filter(r=>String(r.Prioritas||'').toLowerCase()==='kritis'&&statusBucket(r.Status)!=='Selesai').length;
  const komplainTk=tk.filter(r=>String(r.Tipe||'').toLowerCase()==='komplain');
  const komplainOpen=komplainTk.filter(r=>statusBucket(r.Status)!=='Selesai').length;
  const komplainClosed=komplainTk.length-komplainOpen;
  const budgetTotal=bd.reduce((s,r)=>s+num(r.Budget_Rencana),0);
  const realisasi=it.reduce((s,r)=>s+num(r.Total_Item),0);
  const catMap={};
  bd.forEach(r=>{const c=String(r.Kategori).trim();catMap[c]={name:c,budget:num(r.Budget_Rencana),realisasi:0};});
  it.forEach(r=>{const c=String(r.Kategori_RAB||'Umum').trim();if(!catMap[c])catMap[c]={name:c,budget:0,realisasi:0};catMap[c].realisasi+=num(r.Total_Item);});
  const active=tk.filter(r=>statusBucket(r.Status)!=='Selesai');
  const onTime=active.filter(r=>String(r.Updated_At||'').slice(0,10)===today).length;
  const updateCompliance=active.length?Math.round(onTime/active.length*100):100;
  const recentTickets=tk.slice().sort((a,b)=>String(b.Updated_At||b.Timestamp_Submit||'').localeCompare(String(a.Updated_At||a.Timestamp_Submit||''))).slice(0,6)
    .map(r=>({id:String(r.ID).trim(),kategori:String(r.Kategori||r.Tipe||'').trim(),deskripsi:String(r.Deskripsi||'').trim(),
      pic:String(r.Pelapor||'').trim(),status:statusBucket(r.Status),prioritas:String(r.Prioritas||'Normal').trim(),
      tanggal:String(r.Tanggal||'').trim()}));
  const picMap={};
  tk.forEach(r=>{const p=String(r.Pelapor||'-').trim()||'-';if(!picMap[p])picMap[p]={nama:p,aktif:0,selesai:0};
    if(statusBucket(r.Status)==='Selesai')picMap[p].selesai++;else picMap[p].aktif++;});
  return {key:name,name,lokasi:'',statusCounts:sc,kritisAktif,komplainOpen,komplainClosed,
    budget:budgetTotal,realisasi,updateCompliance,
    rabCategories:Object.values(catMap),recentTickets,picWorkload:Object.values(picMap).filter(p=>p.aktif+p.selesai>0)};
});
return [{json:{success:true,generatedAt:new Date().toISOString(),projects}}];

const PS=$('Code - Parse Sched').first().json;
const ri=PS.rabItems.filter(r=>r.Pekerjaan&&r.Pekerja);
