const latest={};
sl.filter(r=>r&&r.ID&&r.No_Item!==''&&r.No_Item!==undefined&&r.No_Item!==null&&r.Status)
  .forEach(r=>{latest[String(r.ID).trim()+'|'+String(r.No_Item).trim()]=String(r.Status).trim().toLowerCase();});
const byWorker={};
ri.forEach(r=>{const no=parseInt(r.No_Item)||1;const st=latest[String(r.Batch_ID).trim()+'|'+no]||'open';
  if(st==='selesai'||st==='reject'||st==='done')return;
  const w=String(r.Pekerja).trim();if(!byWorker[w])byWorker[w]=[];
  byWorker[w].push({proyek:String(r.Proyek||'').trim(),pekerjaan:String(r.Pekerjaan||'').trim(),vol:r.Vol,sat:String(r.Sat||'').trim(),st});});
const out=[];
Object.keys(byWorker).forEach(w=>{
  const wd=pk.find(x=>String(x.Nama||x.nama||'').trim()===w);
  const phone=String(wd?(wd.No_HP||wd.no_hp||''):'').replace(/\D/g,'').replace(/^0+/,'62');
  if(phone.length<9)return;
  let msg='*Pengingat Pekerjaan*\n\nHalo *'+w+'*! Pekerjaan yang masih perlu diselesaikan:\n\n';
  byWorker[w].slice(0,15).forEach((it,i)=>{const m=(it.st==='proses'||it.st==='inprogress')?' (proses)':'';msg+=(i+1)+'. '+it.pekerjaan+' — '+it.vol+' '+it.sat+' ['+it.proyek+']'+m+'\n';});
  msg+='\nMohon update statusnya di aplikasi ya. _TIM Interior_';
  out.push({json:{phone,waMessage:msg,worker:w}});
});
return out;

