// Satu batchGet -> pecah jadi 5 dataset (hemat read: 5 sheet dalam 1 request)
const resp=$input.first().json;
const vr=resp.valueRanges||[];
function toObjs(values,withRow){
  if(!values||values.length<1)return [];
  const header=values[0].map(h=>String(h).trim());
  const out=[];
  for(let i=1;i<values.length;i++){
    const row=values[i]||[];const o={};
    header.forEach((h,c)=>{o[h]=row[c]!==undefined?row[c]:'';});
    if(withRow)o._row=i+1; // header=baris1, data index i -> baris sheet i+1
    out.push(o);
  }
  return out;
}
const tiket=toObjs((vr[0]||{}).values,true);
const rabItems=toObjs((vr[1]||{}).values,false);
const statusLog=toObjs((vr[2]||{}).values,false);
const pekerja=toObjs((vr[3]||{}).values,false);
const recipients=toObjs((vr[4]||{}).values,false);
return [{json:{tiket,rabItems,statusLog,pekerja,recipients}}];

const r=$('Code - Format Rekap').first().json;
if(!r.hasItems||!r.rowsToUpdate||!r.rowsToUpdate.length)return [];
const data=[];
r.rowsToUpdate.forEach(u=>{
  if(!u._row)return; // tanpa baris -> skip (aman)
  // Tiket: kolom L=Status_Workflow, M=Notify_Count
  data.push({range:'Tiket!L'+u._row+':M'+u._row,values:[[u.Status_Workflow,String(u.Notify_Count)]]});
});
if(!data.length)return [];
return [{json:{payload:{valueInputOption:'RAW',data}}}];
